package limiter

type Counter struct {
	remaining int
	limit     int
}

func New(limit int) *Counter {
	return &Counter{
		limit:     limit,
		remaining: limit,
	}
}

// Allow returns true if a request is still within the limit
func (c *Counter) Allow() bool {
	if c.remaining <= 0 {
		c.remaining = 0
		return false
	}
	c.remaining -= 1
	return true
}

package server

package server

import "github.com/therealshek/ac0a3dfd6ddd/run-Q4wpsj/enma-eval-1246218828/workspace/internal/limiter"

type Router struct {
	limit     int
	counter   *limiter.Counter
}

func NewRouter(limit int) *Router {
	return &Router{limit: limit, counter: limiter.New(limit)}
}

func (r *Router) Handle() int {
	if !r.counter.Allow() {
		return 429
	}
	return 200
}
